-- Run in the Supabase SQL Editor after the `public.villas` table (see
-- supabase-schema.sql) has been created. Photo URLs assume the website's
-- assets/photos/villas/ folder has been pushed live at solaceexecutive.com.
-- price_from is left null for all of these (no confirmed rate yet) -- the
-- 10% markup rule applies whenever Kluiver enters an actual rate later,
-- same as yachts.

insert into public.villas (name, area, bedrooms, bathrooms, max_guests, has_pool, living_area_m2, plot_area_m2, description, amenities, price_from, photo_path, photos, sort_order) values

('Villa San Antonio', 'San Antonio', 5, 4, 10, true, 360, null,
 'Een modern huis over twee verdiepingen, verscholen achter bougainville en palmbomen in San Antonio. Ontworpen voor grote gezelschappen zonder concessies aan privacy: het hoofdhuis wordt aangevuld met een zelfstandige tweekamer-annex, rondom een zonnig terras met privézwembad. Binnen vindt u eigentijdse interieurs, een volledig uitgeruste keuken, open haard en smart-tv''s door het hele huis, met het bruisende San Rafael en Ibiza-Stad op enkele minuten afstand.',
 array['Privézwembad met zonneterras','Aangelegde tuin met overdekte pergola-lounge','Zelfstandige tweekamer-annex voor extra privacy','Volledig uitgeruste keuken met vaatwasser en koffiemachine','Airconditioning, centrale verwarming en open haard','Barbecue en tafeltennistafel','5 minuten lopen naar UNVRS','Minuten van San Rafael en Ibiza-Stad'],
 null,
 'https://solaceexecutive.com/assets/photos/villas/villa-san-antonio/hero.jpg',
 array['https://solaceexecutive.com/assets/photos/villas/villa-san-antonio/hero.jpg','https://solaceexecutive.com/assets/photos/villas/villa-san-antonio/pool.jpg','https://solaceexecutive.com/assets/photos/villas/villa-san-antonio/view-aerial.jpg','https://solaceexecutive.com/assets/photos/villas/villa-san-antonio/dining.jpg','https://solaceexecutive.com/assets/photos/villas/villa-san-antonio/kitchen.jpg','https://solaceexecutive.com/assets/photos/villas/villa-san-antonio/living-room.jpg','https://solaceexecutive.com/assets/photos/villas/villa-san-antonio/bedroom-1.jpg','https://solaceexecutive.com/assets/photos/villas/villa-san-antonio/bedroom-2.jpg','https://solaceexecutive.com/assets/photos/villas/villa-san-antonio/bathroom.jpg'],
